-- 2265 🏋️ Exercises from the book "coaching-transition-play-full-sessions-from-the-tactics-of-simeone-guardiola-klo" into the exercise catalog (mig 2191).
-- Every practice the book sets out, in OUR OWN WORDS, with app page numbers
-- (the diagram is the book page).  Written by scripts/exercises/sync.py load.
-- Re-runnable: clears this book's exercises first.
BEGIN;
DELETE FROM exercises WHERE book_id = (SELECT id FROM coaching_books WHERE slug = 'coaching-transition-play-full-sessions-from-the-tactics-of-simeone-guardiola-klo');
INSERT INTO exercises (title, category_id, opposition, moment, source_id, book_id, page_from, page_to, source_ref, coach,
  objective, setup, procedure, rules, progressions, coaching_points, players_text, min_players, max_players,
  area_text, area_length_m, area_width_m, duration_min, has_goals, has_keepers, directional, age_text, sort_order)
SELECT v.t, c.id, v.opp, v.m, b.source_id, b.id, v.pf::int, v.pt::int, v.ref, v.coach, v.obj, v.setup, v.proc, v.rules, v.prog, v.cp,
  v.players, v.mn::int, v.mx::int, v.area, v.len::real, v.wid::real, v.dur::real, v.goals::boolean, v.gk::boolean, v.dir::boolean, v.age, v.so
FROM (VALUES
  ('Continuous transition 8v8, 3 mini goals vs end line', 'transition', 'opposed', 'to_defend', 36, 36, 'Transition Training: Practice Example', NULL, 'Repeatedly switch between attacking, losing the ball and pressing to win it back and counter.', '40 x 60 yard area with 3 mini goals on one end and a goal line on the other; reds in 2-4-2 v whites in 4-4, two coaches outside with balls.', 'Scenario 1: reds start from the goal line and attack the mini goals; when the attack ends the coach feeds whites, reds must transition to defence, win it back and attack again; whites score by dribbling over (or receiving on) the end line. Scenario 2: reds only defend - coaches feed whites alternately from each side, reds high press, win the ball and counter, then switch to press the next ball.', 'Side mini goal 1 point, middle mini goal 2 points; whites score 2 by dribbling/receiving over the end line.', 'Scenario 2 as above: reds defend continuously, coaches alternate feeds so reds must shift the point of the press.', NULL, '8v8 + 2 coaches', 16, 18, '40 x 60 yards', 54.8, 36.6, NULL, true, false, true, NULL, 10),
  ('4v4+2 two-grid possession switch', 'possession', 'overload', 'to_attack', 47, 47, 'Session for Tactical Situation 1: Practice 1', 'Guardiola (Bayern Munich)', 'Fast transition from defence to attack by moving the ball into free space in the other half.', '20 x 25 yard area split into 2 equal grids; two teams of 4 plus 2 blue neutrals, one on each end line.', 'Team in possession keeps the ball in one grid with the neutrals'' help while the other team presses; if defenders win it they quickly play to the neutral in the opposite grid, the whole team moves across and keeps the ball there, and roles swap.', '5-6 passes or 30 seconds of possession = 1 point; winning it and finding the far neutral = 1 point; players unlimited (or 2-3) touches, neutrals 1-2 touches.', 'Practice 2 adds set formations and direction.', 'Defenders shrink space and press collectively; on winning it react quickly with awareness, quick decisions and fast support.', '4v4+2', 10, 10, '20 x 25 yards', 22.9, 18.3, NULL, false, false, false, NULL, 20),
  ('8v8 directional two-zone possession, set formations', 'positional_game', 'overload', 'to_attack', 48, 48, 'Session for Tactical Situation 1: Practice 2', 'Guardiola (Bayern Munich)', 'Win the ball and switch play quickly into the other half using team formations.', '20 x 40 yard area split into 2 grids; two teams of 8 (reds 4-2, yellows 3-3 inside, each with 2 support players on their end line) plus 2 neutrals on the middle line.', 'Same aim as practice 1 but directional: the team in possession keeps the ball with its support players in its half; the team that wins it switches play to the other half and all move across.', '8 consecutive passes = 1 point; reaching a support player and a neutral in one sequence = 2 points; 2-3 touches, neutrals 1-2; on transition the whole team must cross to the other grid within 5 seconds.', NULL, NULL, '8v8+2 (6 inside + 2 end support each)', 18, 18, '20 x 40 yards', 36.6, 18.3, NULL, false, false, true, NULL, 30),
  ('SSG counter into opposition half with support players', 'transition', 'opposed', 'to_attack', 49, 49, 'Session for Tactical Situation 1: Practice 3', 'Guardiola (Bayern Munich)', 'Defend as a unit in one half, win the ball and counter fast into the space in the other half.', '40 x 50 yard area split into 2 halves with full goals and keepers; each team 6 outfield plus 4 outside support players.', 'Yellows attack in the reds'' half with their support players; reds defend, win the ball and counter quickly to the far goal; after the attack the game restarts in the other half and teams swap roles.', 'Goal in attack 1 point, goal from a counter 2 points; attackers unlimited touches (support 1-2), counter team 2-3 touches and a time limit to finish.', NULL, 'Ball-oriented compact pressing; react instantly on winning it with smart runs; high tempo counter, quick combinations, one-touch finishing.', '6v6 + 4 support each + 2 GKs', 22, 22, '40 x 50 yards', 45.7, 36.6, NULL, true, true, true, NULL, 40),
  ('11v11 two-zone counter through wide gates', 'conditioned_game', 'opposed', 'to_attack', 50, 50, 'Session for Tactical Situation 1: Practice 4', 'Guardiola (Bayern Munich)', 'Defend deep in the low zone, win the ball and break out wide into space for a fast counter.', 'Full pitch split into two halves; reds 4-2-3-1 (or 4-4-1-1) v yellows 4-3-3; all start in the reds'' half except one red forward, the yellow centre backs and GK; red wingers wait in blue cone gates on the halfway line.', 'Yellow No.6 starts in the centre circle and yellows attack the reds'' organised block; reds win it and play out wide through the gates to counter, finishing quickly.', 'Yellow goal 1 point; red goal within 10-12 seconds of winning it counts double; only the 2 wingers and No.10 join the counter (4v3); only the yellow No.6 may track back; swap roles after 10 minutes.', NULL, NULL, '11v11', 22, 22, 'full pitch', NULL, NULL, 20.0, true, true, true, NULL, 50),
  ('8v4(+6) press and keep-ball', 'possession', 'overload', 'to_attack', 53, 53, 'Session for Tactical Situation 2: Practice 1', 'Simeone (Atletico Madrid)', 'Keep possession after winning the ball under pressure in a tight space.', '35 x 35 yard area; yellows have 8 inside (2-3-3); reds have 4 midfielders inside and 6 outside (2 centre backs, 2 full backs, 2 forwards) on the edges.', 'Yellows play 8v4 inside; the 4 red midfielders press to win the ball, then reds keep possession using their 6 outside players (10v8).', 'Yellows: 10 passes = 1 point or 12 seconds = 2 points; reds: 8 consecutive passes = 1 point; red outside players may not enter; yellows and red outside players 2 touches.', 'Practice 2 adds end zones (3-zone version).', 'Outnumbered midfielders press as a unit; after winning it, quick one-touch passing, good angles and distances, talk to escape pressure.', '8v4 (+6)', 18, 18, '35 x 35 yards', 32.0, 32.0, NULL, false, false, false, NULL, 60),
  ('Dynamic 3-zone press and keep-ball 10v10', 'possession', 'opposed', 'to_attack', 54, 54, 'Session for Tactical Situation 2: Practice 2', 'Simeone (Atletico Madrid)', 'Win the ball and support play to keep it, with forwards pressing centre backs.', '35 x 40 yards with 2 extra 2.5 yard end zones: 2 red forwards in one, 2 yellow centre backs in the other; both teams 10 in 4-4-2, red back four outside the main area.', 'Yellows keep the ball; when it goes to their centre back zone the red forwards press there; if reds win it they keep possession with outside players and the yellow centre backs can enter the red forwards'' zone to press.', 'Red forwards stay in their zone; yellow 8 passes = 1 point; red 8 passes = 1 point, 12 seconds = 2 points.', 'Practice 3 moves it to a full pitch with goals.', NULL, '10v10', 20, 20, '35 x 40 yards + 2 x 2.5 yard zones', 36.6, 32.0, NULL, false, false, false, NULL, 70),
  ('Full-pitch 3-zone press and quick counter', 'conditioned_game', 'opposed', 'to_attack', 55, 55, 'Session for Tactical Situation 2: Practice 3', 'Simeone (Atletico Madrid)', 'Press in the low zone, win the ball and counter fast with quick combinations in limited space.', 'Full pitch marked into 3 zones with 2 full goals and keepers; red forwards (9, 11) high in a narrow zone with the 2 yellow centre backs, rest in the large zone.', 'Yellow centre back starts and yellows attack; reds defend the low zone, win it and break quickly to the 2 forwards, with at least one red leaving the large zone to support, finishing within 10-12 seconds.', 'The 8 yellows in the large zone may track back only after the ball crosses halfway; yellow centre backs may press in the forwards'' zone; yellow goal 1, red goal 2 if within 10-12 seconds.', NULL, 'Press as a unit first; time the runs with good communication; finish with quality, one touch when possible.', '10v10 + 2 GKs', 22, 22, 'full pitch', NULL, NULL, NULL, true, true, true, NULL, 80),
  ('4v4 defend then 4v2 counter attack', 'transition', 'opposed', 'to_attack', 58, 58, 'Low Zone TS3 (Ranieri): Practice 1', 'Ranieri (Leicester City)', 'Quick switch from defending to a fast counter attack after winning the ball.', '25 x 25 yd box with a full goal and keeper at each end; blues (4) v a team of 2 yellows + 2 whites.', 'Yellows and whites attack the blue goal 4v4. When blues win it the coach shouts a colour; that pair defends a 4v2 counter while the other pair stands still. Same call if the ball goes out or the attackers score, with the coach serving a new ball.', 'Unlimited touches; the 4v2 counter must end within 8-10 seconds.', NULL, 'Play into space early and use pace and space against the two defenders.', '4v4 + 2 GKs', 10, 10, '25 x 25 yards', 22.9, 22.9, NULL, true, true, true, NULL, 90),
  ('Counter attacks in a 3 zone game', 'transition', 'overload', 'to_attack', 59, 59, 'Low Zone TS3 (Ranieri): Practice 2', 'Ranieri (Leicester City)', 'Fast counter attack with a temporary overload straight after a team''s attack ends.', '30 x 40 yd pitch in 3 zones (two 30x10 end zones, 30x20 middle), full goal and keeper at each end; 4 inside players per team plus spare players waiting outside.', 'One team attacks, aiming to get the ball to a team-mate in the end zone to score. When that attack ends, an outside player of the defending team dribbles in a new ball and attacks the other way 4v3(+1), the finishing attacker recovering as the +1; the defender in the end zone steps out. Continuous, high tempo, players rest outside.', 'Only 1 player per team in an end zone; free play or a 10 second limit to finish with 2-3 touches in the end zones.', NULL, NULL, '4v4 + 2 GKs + outside players', 12, NULL, '30 x 40 yards', 36.6, 27.4, NULL, true, true, true, NULL, 100),
  ('Zonal defending then pass to support players', 'transition', 'opposed', 'to_attack', 60, 60, 'Low Zone TS3 (Ranieri): Practice 3', 'Ranieri (Leicester City)', 'Compact ball-oriented defending to win it, then fast forward passing and running to support the counter.', 'Half pitch in 3 zones with 4 mini goals on the end line; blues 7 (4-2-1 shape) defend the mini goals plus 3 blue support players on halfway; yellows 8 (2-3-3).', 'Yellows attack the mini goals from zone 1 (1 point). Blues win it and pass to a support player (directly or via zone 2); the passer sprints into the ''passer zone'' (3) to get the ball back for a point, while the whole blue team steps up from zone 1 into zone 2 before that return pass arrives.', 'Point for a mini goal; point for the return pass received in zone 3.', NULL, 'Press as a unit keeping distances and talking; quick support running at high tempo after winning it.', '7v8 + 3 support players', 18, 18, 'Half pitch', 52.5, 68.0, NULL, true, false, true, NULL, 110),
  ('Full pitch 4 zone counter attack game', 'transition', 'opposed', 'to_attack', 61, 61, 'Low Zone TS3 (Ranieri): Practice 4', 'Ranieri (Leicester City)', 'Win the ball in the defensive third and launch a quick break exploiting an unbalanced opponent.', 'Full pitch with a 10 yd central ''passer zone'' (zone 3); blues 4-4-2 (or 4-4-1-1) defend with 8 outfield players, one striker in the opponent half and a No.10 in the passer zone; yellows 4-3-3 with a keeper.', 'Yellows attack. Blues win it, find the No.10 in the passer zone; any blue then runs forward to take the ball back in zone 3 and break. Once the ball leaves zone 1 the whole team must push up into zone 2 before the return pass in the passer zone.', 'Attack must finish within 15 seconds of winning the ball or restart from the yellow keeper; blue goals count double.', NULL, 'Ball-oriented unit pressing; quick, cohesive forward support, combination play, aggression and clinical finishing.', '11v11', 22, 22, 'Full pitch', 105.0, 68.0, NULL, true, true, true, NULL, 120),
  ('Transition and support play in 3 zones', 'transition', 'overload', 'to_attack', 64, 65, 'Low Zone TS4 (Guardiola): Practice 1', 'Guardiola (Bayern Munich)', 'Keep the ball through the transition from defence to attack and move it up through zones.', '30 x 54 yd area in three 30x18 zones; low zone 5 reds v 5 whites with 3 blue neutrals outside (5v5+3); 2 of each team in the middle zone; 2 of each team plus a neutral on the end line in the high zone.', 'Team in the low zone makes 5-6 passes with the neutrals then plays into the middle zone; 2 per team and 2 neutrals move up to make 4v4(+2). After 5-6 more passes the ball goes to the high zone, where 1 player from each team joins for 3v3(+1). Defenders press to win it and play it back down the zones the same way; continuous.', 'Aim for a maximum of 2 touches.', NULL, 'Move the ball quickly so defenders can''t close; run forward fast to support the next zone for a one-touch return.', '5v5 + 3 neutrals (plus zone players)', 16, NULL, '30 x 54 yards', 49.4, 27.4, NULL, false, false, true, NULL, 130),
  ('Counter via support players in 3 zone SSG', 'transition', 'opposed', 'to_attack', 66, 66, 'Low Zone TS4 (Guardiola): Practice 2', 'Guardiola (Bayern Munich)', 'Win the ball deep and break fast through support players into space behind.', '30 x 45 yd pitch in three 30x15 zones with a full goal and keeper at each end; 5 outfield players per team starting in the low zone; 2 blue support players, one in the middle zone and one in the end zone.', 'Whites start in the low zone and try to score; reds win it, play to the middle-zone support player and all move up, whites tracking back. Once all reds are in the middle zone they can use the end-zone support player and finish quickly. Then restart with roles reversed.', 'Starting team unlimited touches, transition team 2-3 touches, support players 1-2; 5 seconds to move into the next zone or possession is lost.', NULL, NULL, '5v5 + 2 support + 2 GKs', 14, 14, '30 x 45 yards', 41.1, 27.4, NULL, true, true, true, NULL, 140),
  ('Counter into space behind a high defensive line', 'transition', 'opposed', 'to_attack', 67, 67, 'Low Zone TS4 (Guardiola): Practice 3', 'Guardiola (Bayern Munich)', 'Lure opponents deep, win the ball and attack the space behind their defensive line.', 'Full pitch split into halves; reds 4-4-2 compact in their half, whites 4-3-3 starting with their keeper.', 'Whites build 4v2 in their own half and pass into the attacking half, after which movement is free. Reds draw them deep, win it and counter into the open space behind the whites'' line.', 'Red counter must finish within 15 seconds or restart from the white keeper; red goals count double.', NULL, 'Ball-oriented unit pressing; fast running, combinations, 1v1s and finishing in transition.', '11v11', 22, 22, 'Full pitch', 105.0, 68.0, NULL, true, true, true, NULL, 150),
  ('4 (+3) v 4 transition possession game', 'possession', 'overload', 'to_attack', 73, 73, 'Middle Zone TS1 (Klopp): Practice 1', 'Klopp (Borussia Dortmund)', 'Keep possession through the moment of winning the ball.', '8 x 16 yd area; 2 teams of 4 plus 3 blue neutrals; yellows inside with 1 neutral, other 2 neutrals on the end lines, reds spread around the outside.', 'Reds and neutrals keep the ball; yellows press and, once they win it and find a neutral, swap with the reds onto the outside. Continuous with roles reversed.', 'Outside players and end-line neutrals 2 touches, inside neutral 1 touch; 8 straight passes = 1 point.', NULL, NULL, '4v4 + 3 neutrals', 11, 11, '8 x 16 yards', 14.6, 7.3, NULL, false, false, false, NULL, 160),
  ('Counter to either goal in transition game', 'transition', 'overload', 'to_attack', 74, 74, 'Middle Zone TS1 (Klopp): Practice 2', 'Klopp (Borussia Dortmund)', 'Quick counter attacks after winning the ball while opponents are disorganised.', '20 x 50 yd area in 3 zones (20x26 centre, 20x12 ends) with a full goal and keeper at each end; same 4 (+3) v 4 set-up as the previous practice in the centre.', 'Reds and neutrals aim for 8-10 passes; when yellows win it they attack and try to score in either goal as fast as possible.', '2 neutrals and 2 red outside players may defend but cannot enter the end zone before the ball; transition team unlimited touches but a time limit (e.g. 8 seconds).', NULL, NULL, '4v4 + 3 neutrals + 2 GKs', 13, 13, '20 x 50 yards', 45.7, 18.3, NULL, true, true, true, NULL, 170),
  ('6v6 position specific transition game to mini goals', 'transition', 'overload', 'to_attack', 75, 75, 'Middle Zone TS1 (Klopp): Practice 3', 'Klopp (Borussia Dortmund)', 'Fast break attacks after winning the ball while the opposition is unbalanced.', '45 x 60 yd area in 3 zones (45x30 centre, 45x15 ends) with 2 mini goals at each end; 6v6 in the centre with 1 neutral inside and 2 wide; each team has a support player in one end zone.', 'Reds attack a pair of mini goals with neutral help; yellows press, win it and break the other way, scoring only after using their end-zone support player.', 'Free to leave the centre once the support player is used; touch limits vary (support/neutrals 1-2 touches, 2-3 touches in end zones).', NULL, NULL, '6v6 + 3 neutrals + 2 support', 17, 17, '45 x 60 yards', 54.8, 41.1, NULL, true, false, true, NULL, 180),
  ('Position specific transition game with goals and 1v1s', 'transition', 'overload', 'to_attack', 76, 76, 'Middle Zone TS1 (Klopp): Practice 4', 'Klopp (Borussia Dortmund)', 'More game-realistic fast breaks finishing on full goals.', 'As the 45 x 60 yd 3 zone game, but with full goals and keepers, and in each end zone 1 attacker and 1 defender per team instead of support players.', 'Win the ball in the centre, play into the attacker in the end zone and run forward to support and finish.', 'Must pass to the end-zone attacker before scoring; same rules as practice 3.', NULL, 'Defend as a concentrated unit; support the attacker quickly from deep and ask for the ball into space; quick synchronised movements to finish.', '6v6 + 3 neutrals + 1v1 in each end + 2 GKs', 21, 21, '45 x 60 yards', 54.8, 41.1, NULL, true, true, true, NULL, 190),
  ('11v11 middle zone fast break game', 'conditioned_game', 'opposed', 'to_attack', 77, 77, 'Middle Zone TS1 (Klopp): Practice 5', 'Klopp (Borussia Dortmund)', 'Win the ball in the middle third and break forward quickly.', 'Full pitch in 3 equal zones; yellows 4-2-3-1 defend the middle zone, reds 4-3-3 build from their keeper.', 'Reds build up from the back and try to score (no zone limits). Yellows press in the middle zone, win it and counter; restart with the red keeper when the ball goes out.', 'Reds 1 point a goal; yellows 1 point, or 2 if they score within 8-10 seconds of winning it.', NULL, 'Quick one-touch combinations; passes between centre backs or full back and centre back timed with runs in behind.', '11v11', 22, 22, 'Full pitch', 105.0, 68.0, NULL, true, true, true, NULL, 200),
  ('Continuous 5v3 overload dribble attacks', 'transition', 'overload', 'to_attack', 80, 80, 'Middle Zone TS2 (Mourinho): Practice 1', 'Mourinho (Real Madrid)', 'Fast break attacks with a numerical advantage.', '15 x 25 yd area with end lines to dribble across; 2 teams of 5, each starting in its own half.', 'One player passes in from his goal line and his team attacks 5v3, scoring by dribbling over the end line. When the attack ends 2 of them step off and 3 drop back; the other team then attacks 5v3 the other way.', 'Unlimited touches; each attack finishes within 10 seconds.', NULL, NULL, '5v5 (attacks 5v3)', 10, 10, '15 x 25 yards', 22.9, 13.7, NULL, false, false, true, NULL, 210),
  ('Continuous 5v3 overload SSG with goals', 'transition', 'overload', 'to_attack', 81, 81, 'Middle Zone TS2 (Mourinho): Practice 2', 'Mourinho (Real Madrid)', 'Use an overload to finish fast break attacks on goal.', '20 x 40 yd pitch in 3 zones (20x20 centre, 20x10 ends) with full goals and keepers; 8-10 outfield players per team, the rest waiting outside.', 'Always starts in the centre with a 5v3 attack; players can move freely after the first pass, aiming to score within 8-10 seconds. When it ends, 2 attackers step off, 2 from the other team come on and they attack 5v3 the other way.', 'Score within 8-10 seconds.', NULL, NULL, '8-10 per team + 2 GKs', 18, 22, '20 x 40 yards', 36.6, 18.3, NULL, true, true, true, NULL, 220),
  ('5v3 (+2) overload with pole recovery', 'transition', 'overload', 'to_attack', 82, 82, 'Middle Zone TS2 (Mourinho): Practice 3', 'Mourinho (Real Madrid)', 'Exploit a brief numerical advantage on the break before defenders recover.', '30 x 30 yd area with full goals and keepers and 4 poles near the corners; 5 outfield players per team, numbered 1-5.', 'Blues attack from the keeper. When the attack ends the coach calls 2 numbers; those players must run round a corner pole before rejoining. The coach feeds a new ball and the whites counter 5v3, scoring before the 2 recover.', NULL, NULL, 'Sprint to the pole, shorten steps and bend the knees to turn, then sprint back.', '5v5 + 2 GKs', 12, 12, '30 x 30 yards', 27.4, 27.4, NULL, true, true, true, NULL, 230),
  ('Full pitch 3 zone overload transition game', 'transition', 'overload', 'to_attack', 83, 83, 'Middle Zone TS2 (Mourinho): Practice 4', 'Mourinho (Real Madrid)', 'Win it in midfield and counter with a numerical advantage.', 'Full pitch in 3 zones; 8 outfield players per team in a 4-1-3 shape starting in the middle zone, plus 2 neutrals who join only the team in transition to attack.', 'Blues attack 8v8; whites cannot leave the middle zone until the ball is played beyond it. Whites win it and break with the neutrals (10v8) to score; next restart from the keeper of the team that just finished.', 'Touch limits vary (all unlimited/neutrals 3, or all 3/neutrals 2); counter must finish within 10 seconds.', 'Stretch the middle zone to the gap between the penalty areas; let neutrals support the first attacking phase but not the finish.', NULL, '8v8 + 2 neutrals + 2 GKs', 20, 20, 'Full pitch', 105.0, 68.0, NULL, true, true, true, NULL, 240),
  ('Fast breaks with support players in 2 zones', 'transition', 'overload', 'to_attack', 86, 86, 'Middle Zone TS3 (Simeone): Practice 1', 'Simeone (Atletico Madrid)', 'Move from defence to attack with quick support play into the next zone.', '20 x 30 yd area in two 20x15 zones; 4 reds v 4 whites plus 7 blue neutrals around and inside so there are always 4 neutrals per zone.', 'Whites keep the ball with the neutrals in one zone (6-8 passes = 1 point). If reds win it they play quickly into the other zone and sprint across to keep it there; whites follow to win it back. Continuous.', '6-8 passes = 1 point.', NULL, 'After the switch, run fast from behind to support, ask for the ball into space.', '4v4 + 7 neutrals', 15, 15, '20 x 30 yards', 27.4, 18.3, NULL, false, false, true, NULL, 250),
  ('5v5 (+7) transition game with mini goals', 'transition', 'overload', 'to_attack', 87, 87, 'Middle Zone TS3 (Simeone): Practice 2', 'Simeone (Atletico Madrid)', 'Fast break into the next zone with support players and a controlled finish.', '25 x 40 yd area in two zones with 2 mini goals on each end line; 5v5 plus the same 7 blue neutrals.', 'When the defending team wins it they move it quickly into the other zone, combine with the neutrals and score in a mini goal there. They then restart in that zone in possession with roles reversed.', NULL, NULL, 'Run quickly from behind after the switch, ask for it into space and finish with control.', '5v5 + 7 neutrals', 17, 17, '25 x 40 yards', 36.6, 22.9, NULL, true, false, true, NULL, 260),
  ('Full pitch counter with support players', 'transition', 'overload', 'to_attack', 88, 88, 'Middle Zone TS3 (Simeone): Practice 3', 'Simeone (Atletico Madrid)', 'Quick combination play to break and score after winning the ball centrally.', 'Full pitch with a marked central zone; 6 outfield players per team in the zone and a keeper in each goal; 7 blue neutral support players (1 inside, 1 each side, 2 at each end of the zone).', 'Whites build into the box and try to score without the neutrals. If reds win it they counter with all 7 neutrals, aiming to create and score within 12 seconds.', 'Players may run outside the wide support players to overlap or underlap; players 2-3 touches, support players 1-2.', NULL, NULL, '6v6 + 7 neutrals + 2 GKs', 21, 21, 'Full pitch', 105.0, 68.0, NULL, true, true, true, NULL, 270),
  ('4v3 and 1v2 dynamic 2 zone possession', 'possession', 'overload', 'to_attack', 91, 92, 'Middle Zone TS4 (Mourinho): Practice 1', 'Mourinho (Real Madrid)', 'Possession with a numerical advantage and fast support runs into the other zone.', '25 x 25 yd area in 2 equal zones; 2 teams of 5. Blues start 4v3 in one zone and 1v2 in the other.', 'Blues keep it against 3 whites for 5-6 passes, then pass to their lone team-mate in the other zone; 3 blues sprint across to support and 1 white moves over to recreate 4v3 and 1v2. If whites win it first, 1 white comes in from the other zone and 1 blue moves across, so the 4v3 is rebuilt with roles reversed.', 'Unlimited touches, or 2-3 touches.', NULL, 'Close space when out of possession; spread out on winning it; the player joining from the other zone must arrive fast to use the 4v3.', '5v5', 10, 10, '25 x 25 yards', 22.9, 22.9, NULL, false, false, true, NULL, 280),
  ('4 (+2) v 4 possession and transition game', 'possession', 'overload', 'to_attack', 93, 93, 'Middle Zone TS4 (Mourinho): Practice 2', 'Mourinho (Real Madrid)', 'Keep the ball with an overload and support play forward fast after winning it.', '30 x 40 yd area in two 30x20 zones; 2 teams of 6 plus 3 red neutrals. Zone 1: 4 blue midfielders + 2 neutrals (as forwards) v 4 whites; zone 2: 2 blue forwards, 2 white midfielders, 1 neutral.', 'Blues make 6 passes (1 point) then play to a forward in the other zone; 2 blue mids, 2 whites and a neutral move across to rebuild 4 (+2) v 4. If whites win it they pass to team-mates in the other zone and 2 whites run across to support with roles reversed. Continuous.', '6 consecutive passes = 1 point.', NULL, NULL, '6v6 + 3 neutrals', 15, 15, '30 x 40 yards', 36.6, 27.4, NULL, false, false, true, NULL, 290),
  ('Win it centrally and counter in 4 zone game', 'transition', 'overload', 'to_attack', 94, 94, 'Middle Zone TS4 (Mourinho): Practice 3', 'Mourinho (Real Madrid)', 'Exploit a numerical advantage in the centre on the counter attack.', 'Area between the two penalty areas in 4 zones; whites 2-4-2 (from a 4-4-2 diamond), blues 2-2-1-1 (from 4-2-3-1); players stay in their zones against direct opponents.', 'Phase 1: blues build from their keeper through 2v2, 4v3 (whites up) and 2v1 zones to score. Phase 2: whites win it and counter fast, one white allowed to step into the next zone to create an overload (e.g. 5v3 then 3v2). Restart from the blue keeper.', '1 white may move into the next zone on the counter.', NULL, NULL, '8v6 + 2 GKs', 16, 16, 'Between the penalty areas', NULL, NULL, NULL, true, true, true, NULL, 300),
  ('Block wide passes and counter centrally', 'transition', 'overload', 'to_attack', 95, 95, 'Middle Zone TS4 (Mourinho): Practice 4', 'Mourinho (Real Madrid)', 'Force the opponent inside by blocking passes wide, then win it and break with a central overload.', 'As the 4 zone game but with side zones added; whites 4-4-2 diamond add 2 full backs, blues 4-2-3-1 add 2 full backs and 2 wingers in the side zones (2v1 out wide).', 'Blues build from their keeper looking to use their 2v1 on the flanks. Whites block the wide passes, squeeze play into the centre (4v3 in midfield), win it and launch a quick break.', NULL, NULL, 'Draw them inside by blocking wide; use the central 4v3 to win it; fast transition with quick combinations and support runs.', '10v10 + 2 GKs', 22, 22, 'Between the penalty areas plus side zones', NULL, NULL, NULL, true, true, true, NULL, 310),
  ('2v1 (+1) fast breaks to 4 goals', 'transition', 'overload', 'to_attack', 98, 98, 'Middle Zone TS5 (Guardiola): Practice 1', 'Guardiola (Barcelona)', 'Quick decisions on fast breaks against a disorganised defence.', '30 x 30 yd area with a full goal and keeper on each side and a 10 x 10 yd square in the middle; 3 pairs (red, yellow, white). Yellows and whites keep the ball 4v2 around the square against the 2 reds inside.', 'When the reds win it they break to any of the 4 goals; the player on that side defends, with his partner tracking back, giving 2v1 (+1).', 'Second attacker a maximum of 2 touches (control and shoot).', NULL, 'First attacker draws the defender then passes, or attacks himself if the defender covers the runner; second attacker times his run.', '4v2 rondo + 4 GKs', 10, 10, '30 x 30 yards', 27.4, 27.4, NULL, true, true, true, NULL, 320),
  ('Continuous 4v2 attacks in 3 team game', 'transition', 'overload', 'to_attack', 99, 99, 'Middle Zone TS5 (Guardiola): Practice 2', 'Guardiola (Barcelona)', 'Fast break attacks with a numerical advantage.', 'Same 30 x 30 yd area with 2 of the goals removed; 3 pairs (red, yellow, white), keepers in both goals.', 'Two pairs attack 4v2 against the third. When the attack ends the coach gives the defending pair a new ball; the pair that lost it or finished becomes the defenders, and the other pair joins the counter for a new 4v2 the other way.', NULL, 'Add an extra pair or two so players can rest.', 'Receiver drives forward at speed to commit defenders or create space; synchronised movement to finish.', '3 pairs + 2 GKs', 8, 12, '30 x 30 yards', 27.4, 27.4, NULL, true, true, true, NULL, 330),
  ('6v6 game with coach-called counter goals', 'transition', 'opposed', 'to_attack', 100, 100, 'Middle Zone TS5 (Guardiola): Practice 3', 'Guardiola (Barcelona)', 'Fast break attacks in changing game situations.', 'Full pitch with a central zone, 2 mini goals on each sideline and a full goal with a keeper at each end.', 'Reds and whites play 6v6 across the width to the mini goals. When the coach calls ''1'' or ''2'' the team in possession attacks that full goal and everyone may leave the zone; the coach usually calls as a team wins the ball. Then back to 6v6.', NULL, NULL, NULL, '6v6 + 2 GKs', 14, 14, 'Full pitch', 105.0, 68.0, NULL, true, true, true, NULL, 340),
  ('Win it in 5v7 and cross for runners', 'transition', 'opposed', 'to_attack', 101, 101, 'Middle Zone TS5 (Guardiola): Practice 4', 'Guardiola (Barcelona)', 'Win the ball and play quickly wide to cross for runners into the box.', 'Full pitch narrowed to penalty-area width with a central zone; 9 outfield players per team and keepers. 7 whites v 5 reds in the zone; 4 reds wide outside it and 1 white defender in each box.', 'Whites keep the ball 7v5 (6-8 passes = 1 point, 15 seconds = 2). Reds press, win it and play out to a wide red; 2 reds leave the zone and run into the box to finish the cross against 1 defender.', 'Red goal 1 point, 2 points direct from a cross.', '3 red runners against 2 white defenders.', 'Defend collectively; once it is won play wide fast and make supporting runs into the box for the cross.', '9v9 + 2 GKs', 20, 20, 'Full pitch (penalty-area width)', NULL, NULL, NULL, true, true, true, NULL, 350),
  ('Counter with wide players into crosses', 'transition', 'opposed', 'to_attack', 102, 102, 'Middle Zone TS5 (Guardiola): Practice 5', 'Guardiola (Barcelona)', 'Exploit wide players behind the opposition line on the counter.', 'Full pitch with a central zone and 2 side zones; 9 per team including keepers; reds 2-2-3-1 with wingers 7 and 11 in the side zones, whites 4-2-2 who may not enter the side zones.', 'Whites attack; reds defend 6v8 in the main zone, win it and find their wingers, who are free to move once possession is won. They deliver crosses or final balls behind the line while 2-3 central players and the far winger run into the box.', 'Wingers only play in the transition to attack; whites barred from side zones.', NULL, NULL, '9v9 incl. GKs', 18, 18, 'Full pitch', 105.0, 68.0, NULL, true, true, true, NULL, 360),
  ('4 (+3) v 4 two zone possession game', 'possession', 'overload', 'to_attack', 105, 105, 'Middle Zone TS6 (Simeone): Practice 1', 'Simeone (Atletico Madrid)', 'Keep the ball and support play quickly when switching zones after winning it.', '30 x 40 yd area in 2 equal zones; 4 whites v 4 reds plus 3 blue neutrals; reds start on the outside of one zone in possession with the neutrals.', 'Reds make 6-8 passes (1 point) then pass to the neutral in the other zone and everyone moves across to recreate 4 (+3) v 4. Whites press; when they win it they either play into the other zone and take up the outside positions there, or pass to a neutral in the same zone and swap roles with the reds there (1 point).', '6-8 consecutive passes = 1 point.', NULL, NULL, '4v4 + 3 neutrals', 11, 11, '30 x 40 yards', 36.6, 27.4, NULL, false, false, true, NULL, 370),
  ('4 (+3) v 4 two zone possession, both teams inside', 'possession', 'overload', 'to_attack', 106, 106, 'Middle Zone TS6 (Simeone): Practice 2', 'Simeone (Atletico Madrid)', 'Possession through the transition with fast support runs into the next zone.', 'Same 30 x 40 yd 2 zone area, all midfielders or attackers; both teams start inside a zone with 3 neutrals (1 inside, 2 on the lines).', 'Reds keep the ball with the neutrals for 6-8 passes then switch zones. When whites win it they must always play into the other zone and move across to keep it; the team that lost it follows to win it back.', '6-8 passes or a successful switch after winning it = 1 point.', 'Drop one neutral (1 per line) and add a player per team for 5v5 in a zone.', 'After a switch, run quickly from behind to support and ask for it into space.', '4v4 + 3 neutrals', 11, 13, '30 x 40 yards', 36.6, 27.4, NULL, false, false, true, NULL, 380),
  ('7v7 counter with central combination play', 'transition', 'opposed', 'to_attack', 107, 107, 'Middle Zone TS6 (Simeone): Practice 3', 'Simeone (Atletico Madrid)', 'Break quickly with combination play through the centre after winning the ball.', 'Full pitch with a central zone and 2 end zones; 7v7 in the centre (full backs, 3 central mids, 2 wingers), a blue neutral at each end of the central zone acting as centre back or forward, and a 1v1 (striker v centre back) in each end zone with keepers.', 'Team in possession must play to the neutral in the forward role, then to the striker in the end zone; central players run in to support and finish. The defending team wins it and counters the same way. After each attack a new player from each team comes in from the corners with a ball to keep it 7v7, forcing an immediate defensive reaction.', 'Attacks and counters must finish within 10-12 seconds.', NULL, NULL, '7v7 + 2 neutrals + 1v1 in each end + 2 GKs', 22, 26, 'Full pitch', 105.0, 68.0, NULL, true, true, true, NULL, 390),
  ('Four-grid possession game with 8 mini goals', 'transition', 'opposed', 'to_attack', 114, 114, 'Ch6 Tactical Situation 1: Practice 1', 'Claudio Ranieri (Leicester City)', 'Keep the ball under time and space pressure, then switch grids and finish fast after a transition.', '40x40 yard square split into 4 equal grids with 8 mini goals round the edges; two teams of 5 plus 4 neutrals, one neutral parked in each grid. Play begins in one grid with the team in possession outnumbering the other 5(+1)v5.', 'The side on the ball strings 6-8 passes in its grid for a point, then can feed a neutral in another grid; everyone moves across and attacks a mini goal there for 2 points. The defenders press inside the grid, and if they win it they switch play to a neutral in a different grid and go for a mini goal.', 'Each finished attack or dead ball restarts in a new grid with the other team on the ball; a team that scores in all 8 mini goals wins outright.', 'A goal only stands once every player of the scoring team has moved into that grid, forcing the whole team to react to the turnover.', NULL, '5v5 + 4 neutrals', 14, 14, '40 x 40 yards', 36.6, 36.6, NULL, true, false, true, NULL, 400),
  ('6v4 central keep-ball, counter to 4 goals', 'transition', 'opposed', 'to_attack', 115, 115, 'Ch6 Tactical Situation 1: Practice 2', 'Claudio Ranieri (Leicester City)', 'Win the ball in the middle and break out quickly via support players to score.', '50x50 yard area with an 18x18 yard central box; full goals with keepers on all four sides. 6 whites and 4 blues inside the box, 6 more blue support players spread outside near the goals.', 'A keeper feeds the whites, who try to make 8 straight passes in the box for a point. The 4 blues press; once they win it they must find an outside support player inside 4 seconds and then attack any of the 4 goals at speed.', 'Box: whites 2-3 touches, blues free; blues must release to a support player within 4 seconds of winning it. Outside: 1-2 touch finishing, support players 1-2 touches.', NULL, 'Be aggressive after the regain - quick pass out, then positive forward runs; finish inside 4-8 seconds.', '6v4 + 6 support + 4 GKs', 20, 20, '50 x 50 yards (central 18 x 18)', 45.7, 45.7, NULL, true, true, true, NULL, 410),
  ('High press, break into end zone (mini goals)', 'transition', 'opposed', 'to_attack', 116, 116, 'Ch6 Tactical Situation 1: Practice 3', 'Claudio Ranieri (Leicester City)', 'Press high in the opponent''s half and finish a fast break within seconds of winning the ball.', 'Half pitch split at the penalty-area line into a big zone and an end zone; 3 mini goals on the halfway line and 3 on the end line. 8v8: whites in a 4-4 shape building up, blues in 2-2-3-1 or 2-3-3.', 'Whites start with a full back in the corner and build up in the big zone to score in a halfway mini goal (1 point); nobody may enter the end zone yet. Blues press high, and on winning it launch a fast break into the end zone to score in an end-line mini goal while the whites recover.', 'Whites unlimited touches, blues 3 touches; blues must get the ball into the end zone within 5 seconds of winning it and must shoot from inside it; a blue goal within 6-8 seconds counts double.', NULL, NULL, '8v8', 16, 16, 'Half pitch', NULL, NULL, NULL, true, false, true, NULL, 420),
  ('High press, break onto keeper goal', 'transition', 'opposed', 'to_attack', 117, 117, 'Ch6 Tactical Situation 1: Practice 4', 'Claudio Ranieri (Leicester City)', 'Same high press and fast break, now finishing past a goalkeeper.', 'As practice 3 but the 3 end-line mini goals are replaced by a full goal with a keeper; the whites'' keeper starts play to a team-mate in the big zone.', 'Whites build up and score in the halfway mini goals; blues press, win it and race to score in the big goal.', 'As practice 3, but whites get 1 point for 6 passes in a row in the big zone and 2 for a mini-goal score.', NULL, 'Organised, synchronised high pressing in the high zone; finish fast breaks within a maximum of 8 seconds.', '8v8 + GK', 17, 17, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 430),
  ('High press, break to goal, two full goals', 'transition', 'opposed', 'to_attack', 118, 118, 'Ch6 Tactical Situation 1: Practice 5', 'Claudio Ranieri (Leicester City)', 'Press high and break fast, with the building team also attacking a real goal.', 'As practice 4 but the halfway mini goals are removed; a 10-yard zone is marked and a second full goal with a keeper added at the halfway end.', 'Whites build up from their keeper and try to reach the 10-yard zone or score past the other keeper; blues press, win it and break to the far goal.', 'As before, but whites get 1 point for entering the 10-yard zone and 3 for a goal.', NULL, NULL, '8v8 + 2 GKs', 18, 18, 'Half pitch+', NULL, NULL, NULL, true, true, true, NULL, 440),
  ('6(+2)v6 two-zone press and keep-ball swap', 'transition', 'opposed', 'to_attack', 121, 121, 'Ch6 Tactical Situation 2: Practice 1', 'Pep Guardiola (Barcelona)', 'Press to win the ball, then keep it straight after winning it.', 'Area split into 2 equal zones; two teams of 6 plus 2 neutrals. Whites start on the outside edges; inside each zone stand 3 reds and 1 neutral.', 'Whites aim for 8 passes in a row using the neutrals (1 point). Reds press, and when they win it they swap places with the whites on the outside and now try to keep the ball with the neutrals.', '2-3 touches; neutrals 1-2 touches.', NULL, 'Without the ball close the space; with it open the space.', '6v6 + 2 neutrals', 14, 14, '10 x 20 yards (as printed)', 18.3, 9.1, NULL, false, false, false, NULL, 450),
  ('Possession then called-goal fast break with support', 'transition', 'opposed', 'to_attack', 122, 122, 'Ch6 Tactical Situation 2: Practice 2', 'Pep Guardiola (Barcelona)', 'Keep the ball, and on a regain attack a goal named by the coach at speed.', '35x45 yard area with 2 numbered full goals and keepers; 5 whites v 5 reds plus 10 neutral support players on the outside.', 'Scenario 1: keeper feeds whites who aim for 8 passes (1 point), then the coach names a goal to attack; if reds win it they also need 8 passes before attacking the called goal. Scenario 2: on any regain the coach calls a goal and that team breaks at once; one team always keeps the ball and scores, the other always defends and counters.', 'Unlimited or 2-3 touches; neutrals 1 touch; the team breaking from defence must finish within 8 seconds.', NULL, NULL, '5v5 + 10 neutrals + 2 GKs', 22, 22, '35 x 45 yards', 41.1, 32.0, NULL, true, true, true, NULL, 460),
  ('5v5 high-intensity SSG with support players', 'transition', 'opposed', 'to_attack', 123, 123, 'Ch6 Tactical Situation 2: Practice 3', 'Pep Guardiola (Barcelona)', 'Win the ball and finish a fast attack in 8-10 seconds using neutral and support players.', 'Same 35x45 yard area; 5 outfielders per side (3 central midfielders, 2 wingers, a striker); 2 support players beside each goal and 2 neutrals on the sidelines who help the team on the ball.', 'One keeper starts with his team, who build to score using neutrals and support players. Defenders press, win it and make a quick transition to score with the help of neutrals and support players.', 'Inside players unlimited (or 3) touches, neutrals 2, support players 1; the starting team has no time limit, the counter-attacking team must finish inside 8-10 seconds.', NULL, NULL, '5v5 + 2 neutrals + 4 support + 2 GKs', 18, 18, '35 x 45 yards', 41.1, 32.0, NULL, true, true, true, NULL, 470),
  ('8v7 high press game, red goal unguarded', 'transition', 'opposed', 'to_attack', 124, 124, 'Ch6 Tactical Situation 2: Practice 4', 'Pep Guardiola (Barcelona)', 'Press high quickly on the ball and turn a regain into a goal before the opponent reorganises.', 'Full pitch, area marked to 10 yards past halfway; 2 full goals. Reds: 8 outfielders in 2-3-3 with no keeper; whites: 7 outfielders in 2-2-3 plus keeper.', 'Whites always start from their keeper and build up to score. Reds press with the extra man and, on winning it, attack fast to score past the keeper. Having no keeper forces reds to press hard and to recover quickly when they lose it.', 'Whites'' goal after 8 straight passes counts double; reds'' goal within 6 seconds of winning it counts double.', NULL, NULL, '8v7 + GK', 16, 16, 'Full pitch to 10 yards past halfway', NULL, NULL, NULL, true, true, true, NULL, 480),
  ('11v11 high press, run in behind zone', 'conditioned_game', 'opposed', 'to_attack', 125, 125, 'Ch6 Tactical Situation 2: Practice 5', 'Pep Guardiola (Barcelona)', 'Press high as a full team and attack the penalty area fast after winning it.', 'Full width of the pitch with a 10-yard zone behind the reds'' back line; reds add 2 centre backs (4-3-3), whites add 2 full backs and a striker (4-2-3-1 or 4-4-1-1).', 'As practice 4 at 11v11. Whites score 1 for passing into the 10-yard zone behind the reds and 2 for a goal; reds press and finish fast.', 'As practice 4 except the white scoring above.', NULL, 'Win the ball by pressing the carrier and cutting passing lanes; after the regain, play into the box quickly while the opponents are still disorganised.', '11v11', 22, 22, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 490),
  ('5(+1)v5 game, coach calls 1 of 4 goals', 'transition', 'opposed', 'to_attack', 128, 128, 'Ch6 Tactical Situation 3: Practice 1', 'Diego Simeone (Atletico Madrid)', 'Win the ball and break straight away towards a goal the coach calls.', '35x35 yard square with an empty, numbered goal on each side; 5v5 plus 1 neutral who joins the team on the ball.', 'Scenario 1: blues aim for 6-8 passes (1 point), then the coach names a goal for them to attack; reds who win it also need 6-8 passes before going for the called goal. Scenario 2: on every regain the coach calls a goal and that team breaks at once; play restarts with the team that just finished. Scenario 3: one team always keeps the ball and scores, the other always defends and counters.', 'Unlimited or 2-3 touches; neutral 1-2 touches.', 'The coach may call a second number mid-attack to switch the target goal.', NULL, '5v5 + 1 neutral', 11, 11, '35 x 35 yards', 32.0, 32.0, NULL, true, false, true, NULL, 500),
  ('5(+2)v5 called-goal game with keepers', 'transition', 'opposed', 'to_attack', 129, 129, 'Ch6 Tactical Situation 3: Practice 2', 'Diego Simeone (Atletico Madrid)', 'Same called-goal transition game, now finishing past goalkeepers.', 'As practice 1 but 40x40 yards, a keeper in each of the 4 goals and a second neutral.', 'All three scenarios of practice 1 are played with the same objectives and rules.', 'As practice 1.', NULL, 'First pass after the regain goes to a free team-mate so he has time to choose where to attack; from regain to shot in 8 seconds max.', '5v5 + 2 neutrals + 4 GKs', 16, 16, '40 x 40 yards', 36.6, 36.6, NULL, true, true, true, NULL, 510),
  ('6(+2)v6(+2) SSG, support players on transition', 'transition', 'opposed', 'to_attack', 130, 130, 'Ch6 Tactical Situation 3: Practice 3', 'Diego Simeone (Atletico Madrid)', 'Use outside support players to create an overload in the transition to attack.', 'Same area, one goal with keeper each; 5v5 inside (no neutrals) and 2 support players per team outside, one on each side.', 'A keeper starts his team, which tries to score; the other team presses, and on winning it breaks quickly with its support players, who may then come on the pitch. Play restarts from the keeper of the team that just finished.', 'Support players enter only in their team''s transition to attack and may not score; they get 2-3 touches; normal goal 1 point, goal from a transition 2 points.', NULL, NULL, '6(+2)v6(+2) incl. GKs', 16, 16, '40 x 40 yards', 36.6, 36.6, NULL, true, true, true, NULL, 520),
  ('11v11 high press, three-zone counter', 'conditioned_game', 'opposed', 'to_attack', 131, 131, 'Ch6 Tactical Situation 3: Practice 4', 'Diego Simeone (Atletico Madrid)', 'Press high as a team and attack fast while the opponents'' defence is unbalanced.', 'Full pitch, area marked to 15 yards past halfway and split into 3 equal zones. Blues 4-4-2 or 4-4-1-1 building up, reds 4-3-3 pressing.', 'The blue keeper must pass to a blue in zone 1 and blues build up to score. Reds press high; when they win it they break at speed to score.', 'Blues in the zones behind the one where reds win the ball may not track back, so reds attack only those left in that zone; nobody may leave the 3 zones in the first phase, reds are free once they win it, and blues may not enter the end zone until the ball goes in.', NULL, NULL, '11v11', 22, 22, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 530),
  ('11-player build-up, react on coach''s call', 'transition', 'unopposed', 'to_defend', 144, 144, 'Ch8 Tactical Situation 1: Practice 1', 'Jurgen Klopp (Liverpool)', 'Rehearse the whole team''s collective reaction to losing the ball in the low zone.', 'Half pitch, all 11 players in a 4-4-2 (or own formation), play starting from the goalkeeper.', 'The team circulates the ball on the ground out from the back, always moving to support the man on the ball. On the coach''s shout, the player holding the ball becomes the imaginary opponent: the nearest one or two press him, another covers and the rest shift into defensive positions together.', '2-3 touches when playing forward, 1 touch when passing backward.', 'In the first phase play forward then back, continuously front to back.', NULL, '11 (one team)', 11, 11, 'Half pitch', NULL, NULL, NULL, false, true, false, NULL, 540),
  ('9v5 zonal build-up, press on loss', 'transition', 'overload', 'to_defend', 145, 145, 'Ch8 Tactical Situation 1: Practice 2', 'Jurgen Klopp (Liverpool)', 'Build up from the back under pressure and press straight away as a group when the ball is lost.', 'Half pitch split into 4 zones. Yellows: keeper plus 8 in 4-4 (or 4-2-2); reds: 5 (a holding mid, a No.10, two wingers, a striker). Zones give a 2v1 at the back (two centre backs v striker), 4v4 in the big zone and yellow full backs alone in the side zones.', 'From the keeper, yellows build up and keep the ball in their half using the overloads at the back and on the flanks. If they lose it, they switch at once to collective pressing to stop the reds scoring and win it back. Zone limits apply only until yellows lose the ball.', 'Yellow centre backs and full backs 2 touches, the rest free; yellows score 1 for 8 passes in a row and 1 for winning the ball back within 6 seconds; reds score 2 for a goal.', NULL, NULL, '9v5', 14, 14, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 550),
  ('9v6 build-up game, press on loss', 'transition', 'overload', 'to_defend', 146, 146, 'Ch8 Tactical Situation 1: Practice 3', 'Jurgen Klopp (Liverpool)', 'Keep the ball in the build-up and react instantly as a group to win it back after losing it.', 'Half pitch with no zones; as practice 2 but the reds add a second central midfielder.', '9v6 free play with the same aims as practice 2: yellows build up, reds press and try to score, yellows counter-press on loss.', 'Unlimited touches; yellows 1 point for 8 straight passes and 1 for regaining within 6 seconds; reds 2 points per goal.', 'Give reds 2 full backs so outfielders are 8v8, which makes keeping the ball and defending the transition harder.', 'Shut the passing lanes to goal quickly and slow the attack; make the opponents play an extra pass so the team can reorganise.', '9v6', 15, 15, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 560),
  ('11v11 build-up and quick transition to defence', 'conditioned_game', 'opposed', 'to_defend', 147, 147, 'Ch8 Tactical Situation 1: Practice 4', 'Jurgen Klopp (Liverpool)', 'Build up from the back and counter-press collectively when the ball is lost, in a full game.', 'Full pitch, normal 11v11; a full goal and keeper added for the reds. Yellows 4-4-2, reds 4-2-3-1 (adjust to suit).', 'Each attack starts with the yellow keeper; yellows build up to score, and if reds win it the yellows press together to stop the counter and regain it. Restart with the yellow keeper after each finish or dead ball.', 'Unlimited touches; yellow goal 1 point, yellow regain within 6 seconds 1 point; reds must finish their counter within 12 seconds and score 2 for a goal inside that time.', NULL, NULL, '11v11', 22, 22, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 570),
  ('5v5(+2) keep-ball, compact centre on loss', 'transition', 'opposed', 'to_defend', 150, 150, 'Ch8 Tactical Situation 2: Practice 1', 'Pep Guardiola (Man City)', 'Press collectively after losing it to squeeze the centre and stop the opponents playing out.', '25x25 yard square; 5v5 plus 2 neutrals on the sides who play for the team on the ball. Blues start with 2 centre backs outside the bottom edge, 2 central mids inside and a No.10 outside the top edge; all 5 reds inside.', 'Blues try for 6-8 passes in a row with the neutrals (1 point). Reds press; if they win it, the 3 outside blues and 3 inside reds swap places and roles reverse. Blues then press straight away at the right angles to block passes out to the neutrals and win it back.', 'Ball out of play restarts with the same team in possession.', NULL, NULL, '5v5 + 2 neutrals', 12, 12, '25 x 25 yards', 22.9, 22.9, NULL, false, false, false, NULL, 580),
  ('7v5 keep-ball, all seven counter-press', 'transition', 'opposed', 'to_defend', 151, 151, 'Ch8 Tactical Situation 2: Practice 2', 'Pep Guardiola (Man City)', 'Squeeze the centre and win the ball back as fast as possible after losing it.', 'Same 25x25 yard area; the 2 side neutrals become blue full backs, giving 7 blues v 5 reds, with the reds staying inside when they win it.', 'Blues keep the ball; when reds win it, all 7 blues press at once to regain it from the 5 reds.', 'Blues 1 point for 6-8 passes and 1 for a regain within 6 seconds; reds 1 point for keeping it 6-8 seconds, 2 for 6 straight passes.', NULL, 'Make the pitch big when you have the ball and small when you lose it.', '7v5', 12, 12, '25 x 25 yards', 22.9, 22.9, NULL, false, false, false, NULL, 590),
  ('7v5 keep-ball with 4 small goals', 'transition', 'opposed', 'to_defend', 152, 152, 'Ch8 Tactical Situation 2: Practice 3', 'Pep Guardiola (Man City)', 'React fast on losing the ball to protect empty goals and block passing lanes.', 'Same 25x25 yard area with a small goal on each of the 4 sides; all 12 players inside.', 'From the coach''s feed, blues try 6-8 passes then score in any small goal. Reds press, and on winning it try to score; blues must squeeze the centre and close passing options to win it back.', 'Blues 1 point for 6-8 passes plus a goal; reds 1 for winning and keeping it 6 seconds, 2 for a goal; blues 1 for a regain within 6 seconds and 1 more if they then score.', NULL, 'Empty goals punish any free space, so the reaction to loss must be immediate.', '7v5', 12, 12, '25 x 25 yards', 22.9, 22.9, NULL, true, false, true, NULL, 600),
  ('6(+2)v6(+2) SSG, force play wide on loss', 'transition', 'opposed', 'to_defend', 153, 153, 'Ch8 Tactical Situation 2: Practice 4', 'Pep Guardiola (Man City)', 'When outnumbered after losing it, close the centre and push the opponent out wide.', '35x35 yard area with 2 full goals and keepers; 5v5 inside (both 2-2-1) and 2 wingers per team outside on the sides.', 'Normal 5v5 from a keeper. The team that wins the ball can use both its wingers, making 7v5; the team that lost it must squeeze the centre, block the direct route and show play wide, then shift again when the ball goes wide. Restart from the keeper of the team that just finished.', 'Counter-attacks must finish within 8-12 seconds; a regain within 6 seconds scores 1; outside players may come in on their team''s transition (coach decides if they can score).', NULL, NULL, '8v8 incl. GKs', 16, 16, '35 x 35 yards', 32.0, 32.0, NULL, true, true, true, NULL, 610),
  ('Tactical game with side zones, force wide', 'transition', 'opposed', 'to_defend', 154, 154, 'Ch8 Tactical Situation 2: Practice 5', 'Pep Guardiola (Man City)', 'Condense the centre after losing it, block the direct route to goal and push play into the side zones.', 'Bigger area with side zones; blues add 2 full backs (4-2-1), reds add 2 full backs and a striker (4-2-3-1); red wingers sit in the side zones.', 'Blue keeper starts; same objectives and rules as practice 4, but blues are 7 v 10 when reds win it. Blues squeeze the middle and if reds get the ball into a side zone they shift across together to defend and regain it.', 'Red wingers stay in the side zones, 2-3 touches.', NULL, 'Close passing lanes to goal and stop dribbles forward; press together to force the opponents backwards or wide.', '8v11 incl. GKs', 19, 19, NULL, NULL, NULL, NULL, true, true, true, NULL, 620),
  ('1v1 near goal, then recover on a cross', 'one_v_one', 'opposed', 'to_defend', 157, 158, 'Ch8 Tactical Situation 3: Practice 1', 'Pep Guardiola (Man City)', 'Train the switch from attacker to defender in 1v1 duels close to goal.', '20x40 yard area with full goals and keepers at each end; two teams of 3, one player each inside, the other 4 outside on the sides (2 per team, one each side) with balls.', 'The two inside players pass back and forth until the coach shouts; whoever has the ball attacks 1v1 against the other. When that duel ends, roles flip: the coach calls left or right, an outside player from that side crosses a new ball at the other end, and both race there for a second 1v1 where the former attacker now defends.', 'Passing phase 1 touch; first duel unlimited touches; second duel 2 touches.', NULL, NULL, '3v3 + 2 GKs', 8, 8, '20 x 40 yards', 36.6, 18.3, NULL, true, true, true, NULL, 630),
  ('8v8 SSG with called 1v1 in the box', 'transition', 'opposed', 'to_defend', 159, 159, 'Ch8 Tactical Situation 3: Practice 2', 'Pep Guardiola (Man City)', 'React fast after finishing an attack to defend a 1v1 inside your own penalty area.', 'Half pitch zone of about 35x55 yards with 2 full goals and keepers; 8v8 with all players numbered 1-7; 2 yellow crossers by the sidelines near one goal''s penalty area.', 'Normal 8v8 from a keeper. When a team finishes an attack the coach calls a number and a side; the two players with that number sprint into the box, the cross comes from the named side and the player from the team that just attacked must defend it 1v1. Restart from the other keeper with roles reversed.', NULL, NULL, 'The recovering defender must react instantly, get into the box first, goal side and side-on to the ball before clearing.', '8v8 + 2 crossers', 18, 18, '35 x 55 yards', 50.3, 32.0, NULL, true, true, true, NULL, 640),
  ('6v6 press, switch to defend box (6v7)', 'transition', 'opposed', 'to_defend', 160, 162, 'Ch8 Tactical Situation 3: Practice 3', 'Pep Guardiola (Man City)', 'Win the ball, then switch straight back to defending your goal and penalty area while outnumbered.', 'Full width, zone from the edge of the box to halfway with 3 small cone goals on halfway. Blues 4-2 (plus keeper) v reds 4-1-1 or 2-3-1, plus 3 numbered red outside players with balls; 2 yellow crossers by the box.', 'Scenario 1: reds start and attack; if blues win it the coach calls a number and that outside red dribbles in with a new ball, so blues must defend again 6v7. Scenario 2: blues start from their keeper and try to score in a cone goal; when they score or the attack ends a red outside player enters with a new ball. If blues stop the second attack, the coach calls a yellow to cross and everyone may enter the box to attack/defend it.', 'Unlimited touches; reds get 12-14 seconds once an outside player enters, and 6 seconds after a cross is called; reds 1 point per goal; blues 1 for stopping an attack or winning it, 2 for a cone-goal score (scenario 2).', NULL, 'Organised defending in your own half after losing it; guard the central danger zone; press and mark tightly to stop a goal within 8 seconds, then win it.', '6v6 + 3 red extras + 2 crossers + GK', 18, 18, 'Edge of box to halfway, full width', NULL, NULL, NULL, true, true, true, NULL, 650),
  ('8v8 SSG, cross at other end after attack', 'transition', 'opposed', 'to_defend', 163, 163, 'Ch8 Tactical Situation 3: Practice 4', 'Pep Guardiola (Man City)', 'Recover quickly to defend crosses into your own box straight after finishing an attack.', 'Large zone up to the penalty spot, 2 full goals with keepers; 8v8 outfielders plus keepers; 2 yellow red-team crossers by the sidelines at the blues'' end.', 'Blues build up from their keeper to score. When they finish, the coach calls left or right, 3 players from each team sprint into the final zone and the cross comes in; the blues must defend it 3v3. If blues intercept, play goes on; a red goal or dead ball restarts from the blue keeper.', NULL, 'Any number of players from either side may run in to attack or defend the cross.', NULL, '8v8 + 2 GKs + 2 crossers', 20, 20, 'Half pitch to penalty spot', NULL, NULL, NULL, true, true, true, NULL, 660),
  ('6v6+6 game to six mini goals', 'transition', 'overload', 'to_defend', 169, 169, 'Middle Zone TS1 (Klopp): Session Practice 1', 'Klopp (Borussia Dortmund)', 'Constant switching from attack to defence, shutting down quick forward passes after losing the ball.', '40x40 yd box with 3 mini goals on each end line; three teams of 6, one team acts as neutrals placed round the outside.', 'A neutral starts by passing to one team, which uses the neutrals to move the ball forward quickly and score in any of the 3 mini goals. On a turnover the losing side must switch to defence at once, as the winners now attack with the neutrals'' help.', 'Inside players 2-3 touches, neutrals 1-2. Goal = 1 pt, 8 passes in a row before scoring = 2 pts; regaining the ball within 6 seconds of losing it = 1 pt.', NULL, NULL, '6v6+6 (18 players, 3 teams)', 18, 18, '40 x 40 yards', 36.6, 36.6, NULL, true, false, true, NULL, 670),
  ('Four-team game across two parallel grids', 'transition', 'overload', 'to_defend', 170, 170, 'Middle Zone TS1 (Klopp): Session Practice 2', 'Klopp (Borussia Dortmund)', 'Reacting to constantly changing game situations in the defensive transition.', 'Two side-by-side 18x28 yd pitches with full goals and keepers; four teams of 6. Two teams stand as outside neutrals, the other two split 3 per grid, giving two 3v3(+6) games.', 'Inside players are numbered 1-3 and play from the keeper to score. Whenever the ball leaves either game the coach calls two players (e.g. Yellow 2, Red 3) who must sprint to the other grid, read the new picture and take up their role there.', 'Normal goal = 1 pt. Rotate the neutral role often for rest.', 'Coach calls two numbers, or calls a whole colour so all 6 of that team switch grids at once.', NULL, '24 players in 4 teams of 6 + 2 GK', 24, 26, '2 pitches of 18 x 28 yards', 25.6, 16.5, NULL, true, true, true, NULL, 680),
  ('7v7+3 build-up to cone goals with targets', 'transition', 'overload', 'to_defend', 171, 171, 'Middle Zone TS1 (Klopp): Session Practice 3', 'Klopp (Borussia Dortmund)', 'Quick forward build-up from the back plus fast collective reaction after losing the ball.', 'Area from the edge of the box (full goal + GK) to 20 yds past halfway with 3 mini cone goals on the far line. Yellow 7 in a 4-2-1, red 7 in a 2-3-3, plus 3 yellow target players standing in the cone goals.', 'Yellows build from their keeper and score by passing to a team-mate inside a cone goal, who lays it back in and play goes on. Reds press, win it and counter at the big goal; yellows must react together to stop the shot and win it back.', 'Yellows 3 touches, targets 1 touch; reds unlimited but a time limit (e.g. 8-10 s) to finish. Targets may not pass to each other; coach may let targets join the defensive transition.', NULL, NULL, '7v7 + 3 targets + GK', 18, 18, NULL, NULL, NULL, NULL, true, true, true, NULL, 690),
  ('Two-zone positional game with free zone', 'transition', 'opposed', 'to_defend', 172, 172, 'Middle Zone TS1 (Klopp): Session Practice 4', 'Klopp (Borussia Dortmund)', 'Building up and passing into a free central zone, then defending immediately when the ball is lost.', 'Full pitch split into 2 zones with a narrow free zone between. Zone 1: 6 yellows (4-2) v 5 reds (2-3); zone 2: 4 yellows (3-1) v 5 reds (4-1); keepers at both ends.', 'Yellow GK starts; yellows build in zone 1 and pass into the free zone for a dropping team-mate, then must score in zone 2 within 8-10 s. Reds who win it pass into the free zone for their dropping player and must score within 8-10 s, while yellows switch to defend.', 'Unlimited touches. One player per team may drop into the free zone; 8-10 s to finish; restart from the yellow GK if out of play or time expires.', NULL, NULL, '11v11 with GKs', 22, 22, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 700),
  ('11v11 between the penalty boxes', 'conditioned_game', 'opposed', 'to_defend', 173, 173, 'Middle Zone TS1 (Klopp): Session Practice 5', 'Klopp (Borussia Dortmund)', 'Quick defensive transition in the middle third.', 'Area between the two penalty areas, 11v11, yellows 4-2-3-1 v reds 4-3-3, keepers in goal.', 'Yellows start from their keeper and try to score; reds defend as a unit and counter when they win it. Yellows must react straight away to stop the counter and regain the ball.', NULL, NULL, 'The tight space causes frequent turnovers in midfield, so the transition gets lots of reps.', '11v11', 22, 22, 'Between the penalty areas', NULL, NULL, NULL, true, true, true, NULL, 710),
  ('7v7 attack-finish then round the cone', 'transition', 'opposed', 'to_defend', 176, 176, 'Middle Zone TS2 (Klopp): Session Practice 1', 'Klopp (Borussia Dortmund)', 'Fast reactions in the defensive transition right after an attack ends.', '20x40 yd pitch with full goals and keepers; 3 big cones on each sideline. 7v7.', 'Game starts from a keeper. When a team''s attack ends (or on the coach''s signal), all its players must run round one of the side cones while the coach or GK feeds a new ball to the opponents, who counter; the attackers must get back to defend.', 'Unlimited touches; counter team has about 8 s. Goal in first phase = 1, goal on the counter = 2; stopping the counter and winning the ball = 1.', NULL, NULL, '7v7 + 2 GK', 16, 16, '20 x 40 yards', 36.6, 18.3, NULL, true, true, true, NULL, 720),
  ('5v5+4 with inside/outside swap', 'transition', 'overload', 'to_defend', 177, 177, 'Middle Zone TS2 (Klopp): Session Practice 2', 'Klopp (Borussia Dortmund)', 'Getting back quickly after finishing an attack, with roles rotating.', 'Same 20x40 yd area and goals; 5v5 inside, each team has 4 extra players outside the area in the opponents'' half.', 'Yellows build from their GK and attack. Once their attack ends the 4 yellow inside players swap with the 4 yellow outside players, and the red keeper restarts quickly so reds counter before the new yellows are set; the new yellows must recover the ball.', 'Unlimited touches; reds about 8 s to finish. First-phase goal 1, counter goal 2, stopping the counter and winning it 1.', NULL, NULL, '5v5 (+4 each side) + 2 GK', 18, 18, '20 x 40 yards', 36.6, 18.3, NULL, true, true, true, NULL, 730),
  ('11v11 with six numbered balls', 'conditioned_game', 'opposed', 'to_defend', 178, 178, 'Middle Zone TS2 (Klopp): Session Practice 3', 'Klopp (Borussia Dortmund)', 'Collective team shape and reactions when the ball is suddenly in a new area.', 'Full pitch, marked middle zone with 6 numbered balls spread round it; 11v11 (4-2-3-1 v 4-3-3) plus a 7th ball with the GK.', 'Yellows build from their keeper. At any time the coach calls a number: the live ball is kicked out and the defending reds collect the called ball and attack, so yellows must defend from a new spot.', 'Called ball is collected by the defending team (later: both teams race for it). First-phase goal 1, counter goal 2, regaining the ball in the transition 1.', 'Practice 4 (variation) replaces the numbered balls with coach feeds.', NULL, '11v11', 22, 22, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 740),
  ('11v11 with coach feeding the defenders', 'conditioned_game', 'opposed', 'to_defend', 179, 179, 'Middle Zone TS2 (Klopp): Session Practice 4', 'Klopp (Borussia Dortmund)', 'Reacting as a team to a sudden new ball for the opponents anywhere on the pitch.', 'Full pitch without the middle zone or numbered balls; 4-2-3-1 v 4-3-3, coach on the touchline with balls.', 'Whenever the coach wants, he plays a new ball to the defending team; the side in possession kicks theirs out and must switch to defence straight away.', 'Coach always feeds the defending reds (later both teams compete for it). Scoring as in the previous practice.', NULL, NULL, '11v11', 22, 22, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 750),
  ('Four-zone 5v4 then counter to two goals', 'transition', 'overload', 'to_defend', 182, 182, 'Middle Zone TS3 (Guardiola): Session Practice 1', 'Guardiola (Barcelona)', 'Tracking back and restoring balance when instant pressure on the ball is not possible.', '40x40 yd area split into 4 equal grids (2 attacking, 2 defending per team), a full goal with GK in each grid; 2 teams of 5. Attackers play 5v4 in one grid while the defending team''s 5th player waits in the parallel grid.', 'Reds attack in their grid; if the 4 whites win it they pass to their 5th player in the other grid and attack either of the 2 goals there, so all 5 reds must race back to defend.', 'Restart options: same roles from the parallel grid, roles reversed, or keep playing until the ball goes out.', NULL, NULL, '5v5 + 4 GK', 14, 14, '40 x 40 yards', 36.6, 36.6, NULL, true, true, true, NULL, 760),
  ('Two-zone 5v5 with side runners for 6v5', 'transition', 'overload', 'to_defend', 183, 183, 'Middle Zone TS3 (Guardiola): Session Practice 2', 'Guardiola (Barcelona)', 'Recovering into good positions when outnumbered after losing the ball.', '40x40 yd area cut into 2 halves with one goal and GK each; 5v5 plus 4 extras per team on the sidelines (2 per side).', 'Normal game from the keeper. When a team finishes an attack, an opposite-team side player dribbles a new ball in to make 6v5, and the team that just attacked must track back and defend.', '3 touches or unlimited. Counter goal = 1; winning the ball back = 1 and then 12 s to score for 2.', NULL, 'Keep a good shape in possession so you can react; fast tracking back and support to build a strong side.', '5v5 (+4 each) + 2 GK', 20, 20, '40 x 40 yards', 36.6, 36.6, NULL, true, true, true, NULL, 770),
  ('5v5+2 switch defence in middle zone', 'defending', 'overload', 'to_defend', 184, 184, 'Middle Zone TS3 (Guardiola): Session Practice 3', 'Guardiola (Barcelona)', 'Shifting as a back unit to defend a sudden switch of play.', 'Full pitch with middle zone. Reds: back 4 plus a holding midfielder (4-3-3); whites: 5 midfielders in a 2-3, plus 2 white wide players on the halfway line outside the area.', 'Whites keep the ball without attacking while the reds hold shape (press the ball, cover, no tackling). On the coach''s signal he feeds one of the white wide players, who enters to make 7v5 and the whites attack; reds must react together to defend the goal.', 'Whites have 10 s from the wide pass to finish; white goal 2, red stop 1.', 'Reds become 2 attacking mids, 2 wingers and a striker against 2 CBs, 2 FBs, a holder and 2 extras.', 'Drop off to buy time for others to recover, move as a unit and keep distances short.', '5v5+2 + GK', 13, 13, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 780),
  ('8v7+2 switch of play to the weak side', 'transition', 'overload', 'to_defend', 185, 185, 'Middle Zone TS3 (Guardiola): Session Practice 4', 'Guardiola (Barcelona)', 'Collective tracking back to defend a fast break on the weak side.', 'Larger middle zone; 8 red outfield players (2-3-3) v 7 whites (4-2-1) plus 2 white wingers outside the area with a ball each; keepers.', 'Normal game from the red GK. When the coach calls Right or Left the ball in play goes out and that white winger dribbles in to attack the reds'' weak side; reds must transition quickly, now 8v9.', 'No zone limits after the first pass. Red first-phase goal 1, white break goal 2, red recovery 1, red goal after winning it back 2.', NULL, NULL, '8v9 + 2 GK', 19, 19, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 790),
  ('11v11 closing the 30-yard central zone', 'conditioned_game', 'opposed', 'to_defend', 186, 186, 'Middle Zone TS3 (Guardiola): Session Practice 5', 'Guardiola (Barcelona)', 'On losing the ball, everyone squeezes into the centre to block passing lanes to goal.', 'Full pitch, 30 yd central area (penalty-box width) marked out; 11v11, reds 4-3-3 v whites 4-2-3-1.', 'Reds build from their keeper to score while whites press. If reds lose it, all reds move into the central area to cut off central lanes, pushing whites back or wide.', NULL, NULL, 'Immediate press from the nearest player with fast support; centre backs and central midfielders read the situation and converge.', '11v11', 22, 22, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 800),
  ('Shadow shape to numbered mannequins', 'defending', 'unopposed', 'to_defend', 190, 190, 'Middle Zone TS4 (Mourinho): Session Practice 1', 'Mourinho (Real Madrid)', 'Team shape and movement in a rapid switch to defence in midfield.', 'Full pitch with middle zone and 8 numbered mannequins; 10 players in a 4-2-3-1, coach with balls.', 'A defender receives from the coach and the team combines with set patterns. When the coach calls a mannequin number, the team reacts as if that mannequin had the ball: nearest players sprint to close it and block lanes, the rest stay compact. Coach then feeds a new ball.', NULL, NULL, 'Stay compact with short distances; nearest players accelerate to the ball.', '10 players', 10, 11, 'Full pitch', NULL, NULL, NULL, false, false, false, NULL, 810),
  ('11v11 middle zone, three phases', 'conditioned_game', 'opposed', 'to_defend', 191, 193, 'Middle Zone TS4 (Mourinho): Session Practice 2', 'Mourinho (Real Madrid)', 'Team shape and collective pressing after possession is lost, then countering after a win.', 'Same middle zone, 11v11 (4-3-3 v 4-2-3-1), each team with a ball, coaches on both sidelines with balls.', 'Phase 1: both teams combine in the middle zone. Phase 2: coach calls a colour, the other team''s ball goes out, the called team attacks and the others must transition and press, with a new feed on the far side if the attack ends. Phase 3: when the whites win it, the blues freeze while the whites launch a fast break, then everyone sprints back to restart.', 'Limited time to finish after a new ball; a first-attack goal counts double.', NULL, '2 touches (1 for back passes); shift across together, nearest player closes the ball while others mark tightly; after winning it play quickly into space behind with timed supporting runs.', '11v11', 22, 22, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 820),
  ('Three-team two-zone keep-ball and press', 'possession', 'opposed', 'to_defend', 199, 199, 'High Zone TS1 (Mourinho): Session Practice 1', 'Mourinho (Real Madrid)', 'Possession and immediate pressure to recover the ball high up.', '30x40 yd area cut into two zones; 3 teams of 5. Two teams play 5v5 in one zone, the third waits in the other.', 'The team in possession tries to make 8 passes then plays to the waiting team; the defenders then run across to press them. If a defending team wins it they pass to the other zone; the team that lost it must race across to win it back.', 'Unlimited or 3 touches. Winning it within 8 s in the transition and passing to the other zone = 1 pt.', NULL, NULL, '15 players (3 teams of 5)', 15, 15, '30 x 40 yards', 36.6, 27.4, NULL, false, false, true, NULL, 830),
  ('Position-specific 7v7 two-zone game', 'possession', 'opposed', 'to_defend', 200, 200, 'High Zone TS1 (Mourinho): Session Practice 2', 'Mourinho (Real Madrid)', 'Pressing high and the quick switch to defence.', '35x45 yd area in 2 zones. Whites 4-3: back 4 outside the area and 3 central mids inside one zone. Blues 2-3-1 inside that zone with their 7th (No.5) on the far end line.', 'Whites keep it (6-8 passes = 1 pt) while blues press; if blues win it they pass to No.5 and everyone moves across to repeat with roles reversed. Whites must transition quickly but leave one player out on the bottom line to pass to if they regain it.', 'Unlimited or 3 touches. Continuous.', NULL, NULL, '7v7', 14, 14, '35 x 45 yards', 41.1, 32.0, NULL, false, false, true, NULL, 840),
  ('7v7 two-zone game with keepers', 'transition', 'opposed', 'to_defend', 201, 201, 'High Zone TS1 (Mourinho): Session Practice 3', 'Mourinho (Real Madrid)', 'Quick reactions after losing the ball to win it back fast.', '20x40 yd area in 2 halves, keeper on each end; 7v7.', 'Whites keep possession in their half from their GK. Blues try to win it and pass back to their own keeper. Whites first try to stop that pass; if it gets through they rush into the other half and press to win it back and return it to their keeper. Roles flow continuously.', 'Unlimited or 3 touches.', NULL, NULL, '7v7 + 2 GK', 16, 16, '20 x 40 yards', 36.6, 18.3, NULL, true, true, true, NULL, 850),
  ('11v11 high press from a white zone', 'conditioned_game', 'opposed', 'to_defend', 202, 202, 'High Zone TS1 (Mourinho): Session Practice 4', 'Mourinho (Real Madrid)', 'Pressing as a team high up the pitch after a pass is given away.', 'Full pitch with a white zone from halfway back 20 yds; 11v11, whites 4-3-3/4-2-3-1 v blues 4-4-2.', 'Whites pass unopposed in their zone, then deliberately play the ball to a blue in the other half; zone limits end and whites switch to a high press.', 'Blues: pass received behind the white line = 1, goal = 2. Whites: win it and score = 1, win within 8 s and score = 2. Swap roles after a few reps.', NULL, NULL, '11v11', 22, 22, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 860),
  ('11v11 counter-press after losing the ball', 'conditioned_game', 'opposed', 'to_defend', 203, 203, 'High Zone TS1 (Mourinho): Session Practice 5', 'Mourinho (Real Madrid)', 'Synchronised pressing to stop counters when possession is lost high.', 'Full pitch as one zone, final zone behind the whites still marked; 11v11, blues defend deep.', 'Whites build from their keeper and attack; blues defend compact and counter. When whites lose it they press the ball and area together to prevent the counter and regain, then attack again. Scoring as in the last practice.', NULL, NULL, 'Squeeze time and space, mark tight round the ball, stop long balls behind the high line.', '11v11', 22, 22, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 870),
  ('8v8 open-then-close possession game', 'transition', 'overload', 'to_defend', 206, 206, 'High Zone TS2 (Mourinho): Session Practice 1', 'Mourinho (Real Madrid)', 'Quick, efficient reactions in the switch from attack to defence.', '25x25 yd area with full goals and keepers; 2 teams of 8. Whites have 4 outside players on the sides, blues 4 outside on the end lines.', 'White keeper starts; whites keep the ball without scoring (8 passes = 1 pt, 20-25 s = 1 pt). When they lose it they press and close space while blues counter to either goal. Spread out in possession, compress out of it.', 'White inside 2-3 touches, blue inside unlimited, outside players 1-2. Blue goal 1; white regain within 6 s 1. White outside players may come in for the defensive transition; blue outside players never enter or score.', NULL, NULL, '8v8 + 2 GK', 18, 18, '25 x 25 yards', 22.9, 22.9, NULL, true, true, true, NULL, 880),
  ('6v6 small-sided game with cone gates', 'small_sided_game', 'opposed', 'to_defend', 207, 207, 'High Zone TS2 (Mourinho): Session Practice 2', 'Mourinho (Real Madrid)', 'High press to stop forward passes and dribbles in transitions.', '30x40 yd area, full goals with keepers, 5 small cone gates; 6v6 in 2-3-1 or 3-3.', 'Game from a keeper. Points for a pass through a gate (1), a dribble through a gate (2) or a goal (3), which forces the defending team to press the ball carrier hard.', 'Gate pass 1, gate dribble 2, goal 3.', NULL, NULL, '6v6 + 2 GK', 14, 14, '30 x 40 yards', 36.6, 27.4, NULL, true, true, true, NULL, 890),
  ('SSG with no white keeper', 'small_sided_game', 'opposed', 'to_defend', 208, 208, 'High Zone TS2 (Mourinho): Session Practice 3', 'Mourinho (Real Madrid)', 'A fast high press after losing the ball.', 'Same pitch without gates and without the white team''s keeper.', 'Whites start by dribbling in and try to score. When they lose it they must press the new ball carrier at once and stop shots on their empty goal. Team without a keeper always restarts; swap roles after some reps.', 'Whites unlimited touches, blues 2-3. Blue goal 1, white goal 2, white regain within 6 s 1.', NULL, NULL, '6v6 + 1 GK', 13, 13, '30 x 40 yards', 36.6, 27.4, NULL, true, true, true, NULL, 900),
  ('11v11 three-zone high press game', 'conditioned_game', 'opposed', 'to_defend', 209, 209, 'High Zone TS2 (Mourinho): Session Practice 4', 'Mourinho (Real Madrid)', 'Coordinated reactions to losing the ball in high and middle zones.', 'Pitch split into low (15 yds), middle (25 yds) and high (40 yds) zones; whites 4-2-3-1 v blues 4-4-2, free movement.', 'Normal game from the keeper. Lose it high: press the ball at once to force errors. Lose it in midfield: players ahead track back and those behind push up to stop a pass into zone 1.', 'White goal 1, white regain within 6 s 1. Blues: pass received in zone 1 = 1, goal = 2. Whites ahead of the ball in zone 3 who are not back in zone 2 within 6 s give blues 1.', NULL, NULL, '11v11', 22, 22, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 910),
  ('11v11 win it back within 6 seconds', 'conditioned_game', 'opposed', 'to_defend', 210, 210, 'High Zone TS2 (Mourinho): Session Practice 5', 'Mourinho (Real Madrid)', 'Regaining the ball within 6 seconds anywhere on the pitch.', 'Normal 11v11 on the same pitch with no zones.', 'Whites build from their keeper and attack; blues defend and counter. Whenever whites lose it they try to win it back within 6 s.', 'White goal 1, 6 s regain 1, blue goal 2.', NULL, 'Create numbers and a strong side round the ball; avoid fouls when the opponent is under pressure.', '11v11', 22, 22, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 920),
  ('5v5+4 support players, press high', 'transition', 'overload', 'to_defend', 213, 213, 'High Zone TS3 (Guardiola): Session Practice 1', 'Guardiola (Barcelona)', 'Pressing high to block long or short passes through the press.', '40x50 yd area split into two 40x25 halves, full goals with keepers; each team has 5 inside in a 2-3 plus 4 support players around the opponents'' half.', 'Keeper starts; the team in possession attacks into its attacking half and must pass to a support player at least once before scoring. Defenders press high to cut off forward passes and force errors.', 'At least 1 pass to a support player before a goal.', NULL, NULL, '5v5 + 8 support + 2 GK', 20, 20, '40 x 50 yards', 45.7, 36.6, NULL, true, true, true, NULL, 930),
  ('8v7+4 high press, position-specific two zones', 'transition', 'overload', 'to_defend', 214, 215, 'High Zone TS3 (Guardiola): Session Practice 2', 'Guardiola (Barcelona)', 'Pressing high and blocking passes to support players, then defending after losing it.', 'Low zone cut to 40x15 yds; reds 8 outfield (2-3-3), whites 7 inside (4-2-1) plus 4 outside support players.', 'Scenario 1: white GK plays out and reds press high to stop passes to the support players, then try to score; if they lose it they stay high and transition. Scenario 2: red GK starts, reds attack and on a turnover close the ball carrier and block passes to the outside players.', 'Inside players unlimited, white outside 1-2 touches, reds 2-3. White pass to support player 1, white goal 2 (support players cannot score); red regain 1, red goal 2.', 'Remove the 2 red full backs for a harder press.', 'Press high to limit time and space, mark tight round the ball, press the carrier quickly to stop forward play.', '8v7+4 + 2 GK', 21, 21, '40 x 15 yard low zone', NULL, NULL, NULL, true, true, true, NULL, 940),
  ('9v9+4 game with six goals', 'transition', 'overload', 'to_defend', 216, 216, 'High Zone TS3 (Guardiola): Session Practice 3', 'Guardiola (Barcelona)', 'Defensive transition in the high zone of the pitch.', 'Half pitch with full goals at each end and 4 small goals; reds 2-3-3, whites 4-2-1, 4 white support players.', 'Reds build from their keeper to score in the big goal. On losing it they press immediately to stop whites passing to a support player or scoring in any small goal or the far big goal.', 'Red 2-3 touches, white unlimited, support 1-2. Red regain 1, red goal 2; white pass to support 1, small goal 2, big goal 3 (support players cannot score).', NULL, NULL, '9v9+4 + 2 GK', 24, 24, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 950),
  ('Two-zone game with blue support players', 'transition', 'overload', 'to_defend', 217, 217, 'High Zone TS3 (Guardiola): Session Practice 4', 'Guardiola (Barcelona)', 'Instant high press to stop the opponents finding outlets for a counter.', 'Zone 1 = half a full pitch, zone 2 = halfway line to edge of box; reds (2-3-3) start in the high zone v whites in a deep 4-4, 2 blue support players for whites in the low zone.', 'Reds start from their keeper into the high zone and try to score. On losing it they press to stop whites passing to a blue support player; if whites find one they break forward to counter and reds must track back. Once whites win it, everyone may cross zones.', 'Blue support players stay in their zone, 1-2 touches, cannot score and only pass to whites who have entered their zone. Earlier rules apply.', 'Practice 5 (variation): support players work for whichever team has the ball.', NULL, '9v8+2 + 2 GK', 21, 21, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 960),
  ('Two-zone game, support players for both teams', 'transition', 'overload', 'to_defend', 218, 218, 'High Zone TS3 (Guardiola): Session Practice 5', 'Guardiola (Barcelona)', 'High-zone counter-press with the support players helping both teams.', 'Same as Practice 4, but the blue support players play for whoever is in possession.', 'With reds in possession it is 11v9: blues act as red centre backs in a 4-3-3 and stay in the low zone as back-pass options. With whites in possession it is 11v9 for whites: blues play as the two forwards (4-4-2 / 4-4-1-1).', 'Same rules as the previous practice.', NULL, NULL, '9v9+2 + 2 GK', 22, 22, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 970)
) AS v(t, cat, opp, m, pf, pt, ref, coach, obj, setup, proc, rules, prog, cp, players, mn, mx, area, len, wid, dur, goals, gk, dir, age, so)
